// Place in Zabbix frontend under Configuration → Actions → Event correlation rules
{
  "name": "Silence Zabbix agent alerts on test VMs",
  "conditions": [
    {"conditiontype": 12, "operator": 8, "value": "*-test-vm-*"}, // Host name matches
    {"conditiontype": 16, "operator": 2, "value": "Zabbix agent is not available"}, // Problem name contains
    {"conditiontype": 17, "operator": 8, "value": "Average"}, // Severity in minor/warning/info mapped to Average
  ],
  "operations": [
    {
      "operationtype": 7, // Event suppression
      "evaltype": 0,
      "esc_period": 1440 // Silence for 1440 minutes (1 day)
    }
  ]
}

// Trigger expression example for the alert:
// nodata(/vfd-test-vm-03/agent.ping,3m)=1
// This rule suppresses events matching host pattern and message, severity Average (minor/warning/info equivalent) for 1 day
